/* ПОДСВЕТКА КОДА
   Берёт текст из выделенных клеток (одна клетка с переводами строк — тоже
   построчно) и раскладывает его на лист: строка кода — строка листа, каждая
   лексема — своя клетка со своим цветом. Так подсветка живёт в самой таблице:
   её можно копировать, печатать и сохранять.

   Разбирает НЕ сам: лексемы даёт «разметить» — тот же разборщик, которым
   подсвечены редактор модулей книги и поле «код» в формах (в ядре это
   code.rs). Отсюда и языки, и цвета: своих таблиц плагину держать не надо, а
   блочный комментарий, шаблон со вставками и регулярное выражение разбираются
   так же, как в редакторе. */

/* Поля панели и их умолчания. параметры() зовём В ФУНКЦИИ: на верхнем уровне код
   выполняется один раз, при запуске потока, и запомнил бы только умолчания. */
const ПОЛЯ = ({
  язык: {тип: 'список', имя: 'Язык', значения: разметить.языки, умолчание: 'JavaScript'},
  куда: {тип: 'список', имя: 'Куда', значения: ['Справа от выделения', 'Ниже выделения'], умолчание: 'Справа от выделения'},
});

/* Оформление по виду лексемы: цвет даёт сам разборщик, от плагина — шрифт,
   полужирные ключевые слова и курсивные комментарии. Стиль на вид считается
   один раз: клеток бывают десятки тысяч. */
const ШРИФТ = {font: 'Consolas', sz: 10};
const ЖИРНЫЕ = ['ключ'], КУРСИВНЫЕ = ['комментарий'];
const стили = {};
const стильВида = (вид, цвет) => стили[вид] || (стили[вид] = Object.assign({color: цвет || '#000000',
  b: ЖИРНЫЕ.includes(вид) ? 1 : 0, i: КУРСИВНЫЕ.includes(вид) ? 1 : 0}, ШРИФТ));

function Разметить(){
  const п = параметры(ПОЛЯ);
  /* Текст — из выделения: все непустые клетки по строкам, каждая — построчно. */
  const в = книга.выделение;
  const значения = диапазон(в.область).значения;
  const строкиКода = [];
  for(const ряд of значения) for(const v of ряд){
    if(v === null || v === undefined || v === '') continue;
    for(const s of String(v).split('\n')) строкиКода.push(s.replace('\r', ''));
  }
  if(!строкиКода.length) throw new Error('В выделении нет текста. Поставьте курсор на клетку с кодом или выделите строки кода.');

  /* Куда класть: справа — через столбец за выделением, ниже — через строку. */
  const c0 = п.куда === 'Ниже выделения' ? в.c1 : в.c2 + 2;
  const r0 = п.куда === 'Ниже выделения' ? в.r2 + 2 : в.r1;

  /* Размечаем ВЕСЬ текст сразу, а не построчно: иначе блочный комментарий и
     шаблон, идущие через строки, разобрались бы в каждой строке заново. */
  const лексемы = разметить(строкиКода.join('\n'), п.язык);
  let строка = 0, столбец = 0, отступ = '', лексем = 0, ширина = 0;
  for(const л of лексемы){
    const части = л.текст.split('\n');
    for(let k = 0; k < части.length; k++){
      if(k){ строка++; столбец = 0; отступ = ''; }      /* лексема перешла на новую строку */
      const t = части[k];
      if(t === '') continue;
      /* Отступ строки прилипает к первой лексеме: отдельной клеткой он сдвигал
         бы всю разметку вправо. Пробелы внутри строки не нужны — у каждой
         лексемы своя клетка. */
      if(л.вид === 'пробел'){ if(столбец === 0) отступ = t; continue; }
      const к = ячейка(r0 + строка, c0 + столбец);
      к.значение = отступ + t; отступ = '';
      к.стиль = стильВида(л.вид, л.цвет);
      столбец++; лексем++;
      if(столбец > ширина) ширина = столбец;
    }
  }
  сообщить('Размечено строк: ' + (строка + 1) + ', лексем: ' + лексем + ' (' + п.язык
    + '), начиная с ' + ячейка(r0, c0).адрес + '; в самой длинной строке клеток: ' + ширина);
}
